// Package v04run builds the Console-importable Score documents of the REAL
// acceptance application (frontend, backend, worker) from the repository Score
// source (backend/internal/seed/scores.go) and records exactly how they differ
// from that source. It never contacts a cluster, a database or Vault and never
// holds a secret value: the application secret is generated by the scenario at
// run time and only its SHA-256 is a (public) configuration value.
package v04run

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"regexp"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"

	"orchestrator/internal/seed"
)

// Options selects the run-specific values of the Score documents.
type Options struct {
	// Images are the three application images (already loaded into the cluster).
	Frontend, Backend, Worker string
	// Application and Environment scope the Redis keys; RunID separates runs.
	Application, Environment, RunID string
	// DatabaseClass and CacheClass are the provisioning classes the authored
	// Definitions match ("in-cluster" or "cloud-managed"), never an Environment profile.
	DatabaseClass, CacheClass string
	// TTLSeconds is the Redis key TTL the backend and worker use.
	TTLSeconds int
	// DatabaseID and CacheID are the stable shared resource IDs.
	DatabaseID, CacheID string
	// OmitAppSecret drops the optional ACCEPTANCE_SECRET binding (and its public SHA-256). V05/V06 on EKS use it: the
	// run-owned secret-store Vault is bridged to a local cluster and is not reachable from EKS Pods, so the optional secret row
	// is a labelled NOT_CONFIGURED exception there. It never excuses the PostgreSQL/Redis credentials, which always arrive
	// through Kubernetes Secret references.
	OmitAppSecret bool
}

// ConfigKey is one Environment Settings key the generated Scores reference.
type ConfigKey struct {
	Name   string `json:"name"`
	Kind   string `json:"kind"` // variable | secret
	Value  string `json:"value,omitempty"`
	Reason string `json:"reason"`
}

// Change is one recorded difference from the repository Score source.
type Change struct {
	Workload string `json:"workload"`
	Kind     string `json:"kind"`
	Detail   string `json:"detail"`
}

// Workload is one generated Score with the hashes that tie it to its source.
type Workload struct {
	Name       string         `json:"name"`
	Document   map[string]any `json:"-"`
	YAML       string         `json:"-"`
	SourceHash string         `json:"sourceSha256"`
	Hash       string         `json:"sha256"`
}

// Result is the complete, public generation record.
type Result struct {
	Workloads []Workload  `json:"workloads"`
	Config    []ConfigKey `json:"config"`
	Changes   []Change    `json:"changes"`
	// Preserved lists the properties asserted to equal the source (requests/limits, probes, ports, images).
	Preserved []string `json:"preserved"`
}

var ref = regexp.MustCompile(`^\$\{resources\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\}$`)

func hashOf(v any) string {
	raw, _ := json.Marshal(v) // encoding/json sorts map keys: a canonical form
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

func deepCopy(in map[string]any) map[string]any {
	raw, _ := json.Marshal(in)
	var out map[string]any
	_ = json.Unmarshal(raw, &out)
	return out
}

// Build returns the Console Score documents. The base is seed.AcceptanceScoresRedis, so the container
// images, probes, ports and requests/limits of the repository source are preserved verbatim; only the
// differences listed in Result.Changes are applied.
func Build(o Options) (Result, error) {
	if o.Frontend == "" || o.Backend == "" || o.Worker == "" {
		return Result{}, fmt.Errorf("v04run: three application images are required")
	}
	if o.DatabaseClass == "" {
		o.DatabaseClass = "in-cluster"
	}
	if o.CacheClass == "" {
		o.CacheClass = "in-cluster"
	}
	if o.TTLSeconds == 0 {
		o.TTLSeconds = 30
	}
	if o.TTLSeconds < 1 || o.TTLSeconds > 3600 {
		return Result{}, fmt.Errorf("v04run: cache TTL must be between 1 and 3600 seconds")
	}
	if o.DatabaseID == "" {
		o.DatabaseID = "acceptance-db"
	}
	if o.CacheID == "" {
		o.CacheID = "acceptance-cache"
	}
	if o.Application == "" || o.Environment == "" || o.RunID == "" {
		return Result{}, fmt.Errorf("v04run: application, environment and run ID are required")
	}
	base := seed.Defaults()
	base.Images = seed.Images{Frontend: o.Frontend, Backend: o.Backend, Worker: o.Worker}
	base.SharedDatabaseID = o.DatabaseID
	source := seed.AcceptanceScoresRedis(base, o.CacheID, "default", o.Application, o.Environment, o.RunID)

	var result Result
	configs := map[string]ConfigKey{}
	addConfig := func(workload, name, value, kind, reason string) {
		if existing, ok := configs[name]; ok {
			if existing.Value != value {
				// The same key with two values would make one Environment key mean two things.
				panic(fmt.Sprintf("v04run: configuration key %s has conflicting values", name))
			}
			return
		}
		configs[name] = ConfigKey{Name: name, Kind: kind, Value: value, Reason: reason}
	}

	for _, name := range seed.AcceptanceOrder() {
		doc := deepCopy(source[name])
		sourceHash := hashOf(source[name])
		main := doc["containers"].(map[string]any)["main"].(map[string]any)
		variables := main["variables"].(map[string]any)
		resources, _ := doc["resources"].(map[string]any)
		if resources == nil {
			resources = map[string]any{}
			doc["resources"] = resources
		}

		note := func(kind, detail string) {
			result.Changes = append(result.Changes, Change{Workload: name, Kind: kind, Detail: detail})
		}
		if name == "backend" || name == "worker" {
			variables["ACCEPTANCE_CACHE_TTL_SECONDS"] = "${resources.env.ACCEPTANCE_CACHE_TTL_SECONDS}"
			addConfig(name, "ACCEPTANCE_CACHE_TTL_SECONDS", fmt.Sprint(o.TTLSeconds), "variable", "requested per-run Redis key TTL shared by backend and worker")
			note("cache-ttl", fmt.Sprintf("ACCEPTANCE_CACHE_TTL_SECONDS: repository default -> %d seconds", o.TTLSeconds))
			resources["env"] = map[string]any{"type": "environment"}
		}
		// 1. The product's Console accepts container variables only as references: a literal becomes an
		// Environment Settings key referenced as ${resources.env.NAME}.
		literals := []string{}
		keys := make([]string, 0, len(variables))
		for key := range variables {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			value, _ := variables[key].(string)
			if strings.Contains(value, "${") {
				continue
			}
			if (name == "backend" || name == "worker") && key == "ACCEPTANCE_CACHE_TTL_SECONDS" {
				continue // replaced with the requested shared Environment TTL below
			}
			if name == "frontend" && key == "BACKEND_URL" {
				continue // replaced below by the Service reference
			}
			variables[key] = "${resources.env." + key + "}"
			addConfig(name, key, value, "variable", "literal variable of the repository Score source became an Environment key")
			literals = append(literals, key)
		}
		if len(literals) > 0 {
			note("literal-to-environment-key", strings.Join(literals, ","))
			resources["env"] = map[string]any{"type": "environment"}
		}
		// 2. In-cluster classes: the authored Definitions are selected by class, not an Environment profile.
		if db, ok := resources["db"].(map[string]any); ok {
			db["class"] = o.DatabaseClass
			note("class", "db: default -> "+o.DatabaseClass)
		}
		if cache, ok := resources["cache"].(map[string]any); ok {
			cache["class"] = o.CacheClass
			note("class", "cache: default -> "+o.CacheClass)
		}
		// 3. Deployment checks of the acceptance application (README): config, secret and its public hash.
		if name == "backend" {
			variables["ACCEPTANCE_CONFIG"] = "${resources.env.ACCEPTANCE_CONFIG}"
			addConfig(name, "ACCEPTANCE_CONFIG", "acceptance-config-ok", "variable", "expected configuration value of the deployment check")
			resources["env"] = map[string]any{"type": "environment"}
			if o.OmitAppSecret {
				note("added-check-config", "ACCEPTANCE_CONFIG (the optional ACCEPTANCE_SECRET binding is NOT configured on this target)")
			} else {
				variables["ACCEPTANCE_SECRET"] = "${resources.env.ACCEPTANCE_SECRET}"
				variables["ACCEPTANCE_SECRET_SHA256"] = "${resources.env.ACCEPTANCE_SECRET_SHA256}"
				addConfig(name, "ACCEPTANCE_SECRET", "", "secret", "secret generated by the scenario; only its SHA-256 is public")
				addConfig(name, "ACCEPTANCE_SECRET_SHA256", "", "variable", "SHA-256 of the generated secret, filled by the scenario")
				note("added-check-config", "ACCEPTANCE_CONFIG, ACCEPTANCE_SECRET (secret), ACCEPTANCE_SECRET_SHA256")
			}
		}
		// 4. The frontend reaches the backend through the Service reference, not a literal URL.
		if name == "frontend" {
			variables["BACKEND_URL"] = "${resources.backend.url}"
			resources["backend"] = map[string]any{"type": "service", "params": map[string]any{"workload": "backend", "port": "http"}}
			note("service-reference", "BACKEND_URL: http://backend:8080 -> ${resources.backend.url}")
		}

		yamlBytes, err := yaml.Marshal(doc)
		if err != nil {
			return Result{}, err
		}
		result.Workloads = append(result.Workloads, Workload{Name: name, Document: doc, YAML: string(yamlBytes), SourceHash: sourceHash, Hash: hashOf(doc)})
		// Properties that must equal the repository source.
		for _, property := range preservedProperties(source[name], doc) {
			result.Preserved = append(result.Preserved, name+": "+property)
		}
	}
	names := make([]string, 0, len(configs))
	for name := range configs {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		result.Config = append(result.Config, configs[name])
	}
	if err := Validate(result); err != nil {
		return Result{}, err
	}
	return result, nil
}

// preservedProperties names the properties that equal the source, so the record can state them.
func preservedProperties(source, generated map[string]any) []string {
	var out []string
	src := source["containers"].(map[string]any)["main"].(map[string]any)
	gen := generated["containers"].(map[string]any)["main"].(map[string]any)
	for _, property := range []string{"image", "readinessProbe", "livenessProbe", "resources"} {
		if hashOf(src[property]) == hashOf(gen[property]) {
			if _, present := src[property]; present {
				out = append(out, property)
			}
		}
	}
	if hashOf(source["service"]) == hashOf(generated["service"]) && source["service"] != nil {
		out = append(out, "service")
	}
	return out
}

// Validate proves the generated documents keep the contract the product and the application need.
func Validate(r Result) error {
	byName := map[string]Workload{}
	for _, w := range r.Workloads {
		byName[w.Name] = w
	}
	for _, name := range []string{"backend", "worker", "frontend"} {
		if _, ok := byName[name]; !ok {
			return fmt.Errorf("v04run: workload %s is missing", name)
		}
	}
	for _, w := range r.Workloads {
		main := w.Document["containers"].(map[string]any)["main"].(map[string]any)
		for key, value := range main["variables"].(map[string]any) {
			text, _ := value.(string)
			if !ref.MatchString(text) {
				return fmt.Errorf("v04run: %s variable %s is not a resource reference", w.Name, key)
			}
		}
	}
	// backend and worker bind the SAME shared database and cache IDs: one PostgreSQL and one Redis.
	ids := func(name, alias string) string {
		resources := byName[name].Document["resources"].(map[string]any)
		entry, _ := resources[alias].(map[string]any)
		id, _ := entry["id"].(string)
		return id
	}
	for _, alias := range []string{"db", "cache"} {
		if ids("backend", alias) == "" || ids("backend", alias) != ids("worker", alias) {
			return fmt.Errorf("v04run: backend and worker must share one %s resource ID", alias)
		}
	}
	// Secret values never appear in a Score: the only secret key is referenced, never given a value.
	for _, key := range r.Config {
		if key.Kind == "secret" && key.Value != "" {
			return fmt.Errorf("v04run: secret key %s carries a value", key.Name)
		}
	}
	return nil
}

// ProbeScore is the V2-E02 controlled-failure workload. Its run-specific Redis Definition uses a syntactically
// valid, operator-verified missing image digest; Terraform creates the provider object and readiness then fails.
// The workload is blocked, and the run retains the failed provider evidence for cleanup/recovery.
func ProbeScore(o Options) (string, map[string]any, error) {
	if o.Frontend == "" {
		return "", nil, fmt.Errorf("v04run: the frontend image is required")
	}
	doc := map[string]any{
		"apiVersion": "score.dev/v1b1",
		"metadata":   map[string]any{"name": "probe"},
		"containers": map[string]any{"main": map[string]any{
			"image":     o.Frontend,
			"variables": map[string]any{"PORT": "${resources.env.PORT}", "REDIS_HOST": "${resources.cache.host}"},
		}},
		"resources": map[string]any{
			"env":   map[string]any{"type": "environment"},
			"cache": map[string]any{"type": "redis", "class": "readiness-probe", "id": "readiness-probe"},
		},
	}
	raw, err := yaml.Marshal(doc)
	return string(raw), doc, err
}

// PreApplyProbeScore is V04 E01: a distinct run-owned PostgreSQL resource has a
// schema-valid but Terraform-invalid database identifier, so validation fails
// during plan before Kubernetes creates a provider object.
func PreApplyProbeScore(o Options) (string, map[string]any, error) {
	if o.Frontend == "" || o.RunID == "" {
		return "", nil, fmt.Errorf("v04run: frontend image and run ID are required")
	}
	doc := map[string]any{
		"apiVersion": "score.dev/v1b1", "metadata": map[string]any{"name": "probe-e01"},
		"containers": map[string]any{"main": map[string]any{"image": o.Frontend, "variables": map[string]any{"PORT": "${resources.env.PORT}", "PGHOST": "${resources.database.host}"}}},
		"resources": map[string]any{
			"env":      map[string]any{"type": "environment"},
			"database": map[string]any{"type": "postgres", "class": "invalid-name-probe", "id": "v04-e01-" + o.RunID, "params": map[string]any{"database": "Bad.Name", "username": "app"}},
		},
	}
	raw, err := yaml.Marshal(doc)
	return string(raw), doc, err
}
